import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionUser = (String) req.getSession().getAttribute("username");
        if (sessionUser == null) {
            resp.sendError(401);
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        // Validate report type against allowed values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = buildQuery(reportType, dateRange, department, sessionUser);
            log.info("Executing report query for user: " + sessionUser);

            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(query)) {
                StringBuilder json = new StringBuilder("[\n");
                ResultSetMetaData meta = rs.getMetaData();
                int cols = meta.getColumnCount();
                boolean first = true;
                while (rs.next()) {
                    if (!first) json.append(",\n");
                    json.append("  {");
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) json.append(", ");
                        json.append("\"").append(meta.getColumnName(i)).append("\": ");
                        json.append("\"").append(rs.getString(i)).append("\"");
                    }
                    json.append("}");
                    first = false;
                }
                json.append("\n]");
                out.print(json.toString());
            }
        } catch (SQLException e) {
            log.severe("SQL error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    private String buildQuery(String type, String range, String dept, String user) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports_").append(type);
        sb.append(" WHERE owner = '").append(user).append("'");

        if (range != null) {
            String[] parts = range.split("_");
            sb.append(" AND created_at BETWEEN '").append(parts[0])
              .append("' AND '").append(parts[1]).append("'");
        }

        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department = '").append(dept).append("'");
        }

        sb.append(" ORDER BY created_at DESC LIMIT 500");
        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        if (type == null) return false;
        return type.equals("sales") || type.equals("inventory")
            || type.equals("hr") || type.equals("finance");
    }
}
